### 3.1 Core Express Hardening (add to `app.js`)

```js
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');

// Security headers
app.use(helmet());

// CORS – restrict to known origins (adjust as needed)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'https://myapp.example.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
}));

// Rate limiting – 100 requests per 15 minutes per IP (tune for your traffic)
