const express = require('express');
const helmet   = require('helmet');
const cors     = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ---- Security middleware -------------------------------------------------
app.use(helmet());                     // Sets a solid baseline of security headers
app.use(cors({                         // Restrict allowed origins (adjust as needed)
  origin: ['https://my-trusted-domain.com'],
  methods: ['GET','POST','OPTIONS'],
  allowedHeaders: ['Content-Type','Authorization']
}));

// Rate limiting: 100 requests per 15 min per IP (tune for your traffic)
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
}));

// Simple request logger (avoid logging sensitive data)
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next();
});

// -------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/* ==== USER ENDPOINT ==== */
// NOTE: In a real system this should be protected (auth + RBAC) and
//       should never return raw e‑mail addresses.
app.get('/users', (req, res) => {
  // Example: strip PII for unauthenticated callers
  const safeUsers = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(safeUsers);
});

/* ==== Global error handler ==== */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

/* ==== Graceful shutdown ==== */
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received – shutting down gracefully...');
  server.close(() => process.exit(0));
});

module.exports = app;
```

