## 3. Recommended Refactor (Minimal Secure Baseline)

Below is a **drop‑in replacement** that addresses the high‑impact issues while preserving the existing functionality. It adds secure defaults and is ready for future expansion.

```js
// app.js
// Secure baseline for the simple Express demo

/* -------------------- DEPENDENCIES -------------------- */
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const cors = require('cors');          // optional, configure as needed
require('dotenv').config();            // loads .env (PORT, NODE_ENV, etc.)

/* -------------------- APP SETUP -------------------- */
const app = express();

// ---- Security middleware ----
app.use(helmet());                     // sets a comprehensive set of security headers
app.disable('x-powered-by');           // hide Express fingerprint
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' })); // tighten in prod

// ---- Rate limiting (basic) ----
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: process.env.RATE_LIMIT_MAX || 100, // limit per IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---- Logging ----
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

/* -------------------- ROUTES -------------------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// In a real app this would be protected (auth + proper scoping)
// For demo purposes we keep it but strip sensitive data.
app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice' }, // email removed
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

/* -------------------- ERROR HANDLING -------------------- */
// Catch all 404s
app.use((_req, _res, next) => {
  const err = new Error('Not Found');
  err.status = 404;
  next(err);
});

// Centralised error handler – never leak stack traces to the client
app.use((err, _req, res, _next) => {
  // Log the error internally
  console.error(err);
  const status = err.status || 500;
  res.status(status).json({
    error: {
      message: status === 500 ? 'Internal Server Error' : err.message,
    },
  });
});

/* -------------------- SERVER -------------------- */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

/* Export for testing */
module.exports = app;
```

### What the Refactor Adds
| Feature | Reason |
|---------|--------|
| `helmet` | Secure default HTTP headers (CSP, HSTS, X‑Frame‑Options, etc.). |
| `app.disable('x-powered-by')` | Prevents exposing the framework name. |
| `express-rate-limit` | Mitigates DoS/brute‑force attempts. |
| `morgan` | Provides request logs for audit trails. |
| `dotenv` | Enables environment‑based configuration (port, CORS origins, rate limits). |
| Centralized error handling | Guarantees that stack traces never reach the client. |
| Sanitised `/users` response | Removes e‑mail addresses to avoid data leakage. |
| Optional CORS configuration | Allows you to lock down origins in production. |

